export function dirFromYaw(yaw: number): { x: number; z: number } {
  return { x: -Math.sin(yaw), z: -Math.cos(yaw) };
}

/** World yaw that points along (dx, dz). */
export function yawFromDir(dx: number, dz: number): number {
